# Auto-generated: installs dedicated S4RAS portal logo assets (favicon.ico, logo192.png, logo512.png)
# Run from the repo root: powershell -ExecutionPolicy Bypass -File scripts\install-logo-assets.ps1
$ErrorActionPreference = "Stop"
$pub = Join-Path $PSScriptRoot "..\public"

$favicon_ico = ""
[IO.File]::WriteAllBytes((Join-Path $pub "favicon.ico"), [Convert]::FromBase64String($favicon_ico)) 

$logo192_png = ""
[IO.File]::WriteAllBytes((Join-Path $pub "logo192.png"), [Convert]::FromBase64String($logo192_png)) 

$logo512_png = ""
[IO.File]::WriteAllBytes((Join-Path $pub "logo512.png"), [Convert]::FromBase64String($logo512_png)) 

Write-Host "Portal logo assets written to $pub"
